using System;
using System.IO;
using System.Security.Cryptography;
#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
#else
using System.Text.Json;
#endif

namespace ControlLab.UnityPrototype
{
    /// <summary>
    /// Runs the same numerical comparison in Unity or the standalone .NET runner.
    /// Replays frozen reference steps originally generated by Python TeachingSimulation.
    /// The retired Python project is not required; the .NET path needs no Unity licence.
    /// </summary>
    public static class PhysicsVerification
    {
        private const double Tolerance = 1e-10;

        [Serializable] public class Fixture { public int schema; public Case[] cases; }
        [Serializable] public class Case { public string name; public Row[] rows; }
        [Serializable] public class Row
        {
            public string op;
            public double value, x, v, theta, omega, force, disturbance, net, time;
            public int index;
            public bool running, fallen, dragging;
            public string reason;
        }
        [Serializable] public class Report
        {
            public bool passed;
            public string runtime, utc, fixturePath, modelSha256;
            public double tolerance = Tolerance;
            public int cases, operations, numericComparisons, lifecycleComparisons;
            public int invariantChecks;
            public double maxAbsoluteError;
            public string worstLocation = "none", failure = "";
        }

#if UNITY_EDITOR
        [MenuItem("ControlLab/Verify Physics Against Frozen Reference")]
        public static void Run()
        {
            string root = Directory.GetParent(Application.dataPath).FullName;
            string output = Path.Combine(root, "Logs", "Verification");
            Report report = Verify(Path.Combine(root, "Tools", "PhysicsCheck", "Fixtures", "physics-golden.json"),
                Path.Combine(output, "physics-verification-unity.json"), "Unity " + Application.unityVersion,
                Path.Combine(root, "Assets", "ControlLab", "Scripts", "PendulumModel.cs"));
            Debug.Log("ControlLab physics verified: " + report.operations + " operations; max error "
                + report.maxAbsoluteError.ToString("R") + ".");
        }
#endif

        public static Report Verify(string fixturePath, string reportPath, string runtime, string modelPath)
        {
            if (!File.Exists(fixturePath))
                throw new FileNotFoundException("The frozen fixture is missing. Restore Tools/PhysicsCheck/Fixtures/physics-golden.json "
                    + "from this Unity project's source control; retired Python code is not required.", fixturePath);
            Report report = new Report { runtime = runtime, utc = DateTime.UtcNow.ToString("O"),
                fixturePath = Path.GetFullPath(fixturePath) };
            try
            {
                string source = Path.GetFullPath(modelPath);
                using (SHA256 sha = SHA256.Create())
                    report.modelSha256 = BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(source))).Replace("-", "").ToLowerInvariant();
#if UNITY_EDITOR
                Fixture fixture = JsonUtility.FromJson<Fixture>(File.ReadAllText(fixturePath));
#else
                Fixture fixture = JsonSerializer.Deserialize<Fixture>(File.ReadAllText(fixturePath),
                    new JsonSerializerOptions { IncludeFields = true });
#endif
                Require(fixture != null && fixture.schema == 1 && fixture.cases != null && fixture.cases.Length > 0,
                    "Missing or unsupported reference fixture.");
                foreach (Case test in fixture.cases)
                {
                    PendulumModel model = new PendulumModel();
                    ++report.cases;
                    for (int i = 0; i < test.rows.Length; ++i)
                    {
                        Row expected = test.rows[i];
                        Apply(model, expected);
                        string location = test.name + "[" + i + "] " + expected.op;
                        Compare(model.X, expected.x, location + ".x", report);
                        Compare(model.V, expected.v, location + ".v", report);
                        Compare(model.Theta, expected.theta, location + ".theta", report);
                        Compare(model.Omega, expected.omega, location + ".omega", report);
                        Compare(model.Force, expected.force, location + ".force", report);
                        Compare(model.DisturbanceForce, expected.disturbance, location + ".disturbance", report);
                        Compare(model.NetForce, expected.net, location + ".net", report);
                        Compare(model.Time, expected.time, location + ".time", report);
                        Require(model.StepIndex == expected.index && model.IsRunning == expected.running
                            && model.HasFallen == expected.fallen && model.IsDragging == expected.dragging
                            && model.EndReason == expected.reason, location + ": lifecycle mismatch");
                        report.lifecycleComparisons += 5;
                        ++report.operations;
                    }
                }
                CheckInvariants(report);
                report.passed = true;
            }
            catch (Exception error)
            {
                report.failure = error.ToString();
                throw;
            }
            finally
            {
                Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(reportPath)));
#if UNITY_EDITOR
                File.WriteAllText(reportPath, JsonUtility.ToJson(report, true));
#else
                File.WriteAllText(reportPath, JsonSerializer.Serialize(report,
                    new JsonSerializerOptions { IncludeFields = true, WriteIndented = true }));
#endif
            }
            return report;
        }

        private static void Apply(PendulumModel model, Row row)
        {
            switch (row.op)
            {
                case "reset": model.Reset(); break;
                case "begin": model.BeginDrag(); break;
                case "drag": model.DragTo(row.value); break;
                case "end": model.EndDrag(); break;
                case "nudge": model.Nudge(); break;
                case "tick": model.Tick(); break;
                default: throw new ArgumentException("Unknown fixture operation: " + row.op);
            }
        }

        private static void Compare(double actual, double expected, string location, Report report)
        {
            double error = Math.Abs(actual - expected);
            Require(!double.IsNaN(actual) && !double.IsInfinity(actual), location + ": nonfinite result");
            if (error > report.maxAbsoluteError)
            { report.maxAbsoluteError = error; report.worstLocation = location; }
            ++report.numericComparisons;
            Require(error <= Tolerance, location + ": absolute error " + error.ToString("R"));
        }

        private static void CheckInvariants(Report report)
        {
            PendulumModel model = new PendulumModel();
            model.Tick();
            Require(model.Time == 0 && model.X == 0 && model.Theta == 0 && !model.IsRunning,
                "Initial/reset pose must be exactly upright and stationary.");
            ++report.invariantChecks;
            model.BeginDrag();
            model.DragTo(0.2);
            model.Tick();
            Require(model.X == 0 && model.Theta == 0 && model.V > 0 && model.Omega < 0,
                "First step must use explicit Euler, without teleporting the cart or pole.");
            ++report.invariantChecks;
            double previousV = model.V;
            model.EndDrag();
            Require(model.V == previousV && model.IsRunning, "Release must preserve inertia.");
            model.Tick();
            Require(Math.Abs(model.X - PendulumModel.Dt * previousV) < Tolerance,
                "Release must continue physical motion.");
            ++report.invariantChecks;
            bool rejected = false;
            try { model.DragTo(double.NaN); } catch (ArgumentOutOfRangeException) { rejected = true; }
            Require(rejected, "Nonfinite pointer input must be rejected.");
            ++report.invariantChecks;
            model.Reset();
            model.Nudge();
            for (int i = 0; i < 5; ++i)
            { model.Tick(); Require(model.DisturbanceForce == 1, "Nudge must be +1 N for five steps."); }
            model.Tick();
            Require(model.DisturbanceForce == 0, "Nudge must stop after 0.10 simulated seconds.");
            ++report.invariantChecks;
            while (model.IsRunning && model.Time < 10) model.Tick();
            Require(model.HasFallen, "A disturbed open-loop pole must fall; no hidden balancing is allowed.");
            double fallenX = model.X;
            model.BeginDrag();
            Require(model.X == Math.Max(-2.3, Math.Min(2.3, fallenX)) && model.Theta == 0
                && model.V == 0 && model.Omega == 0 && model.Time == 0 && model.IsRunning,
                "Regrab must start upright at the current bounded position.");
            ++report.invariantChecks;
            model.Reset();
            model.BeginDrag();
            for (int i = 0; i < PendulumModel.MaxSteps; ++i) model.Tick();
            Require(model.HasFallen && model.EndReason == "time_limit" && model.Time == 10000
                && model.X == 0 && model.Theta == 0, "Free exploration time limit or resting equilibrium changed.");
            ++report.invariantChecks;
        }

        private static void Require(bool condition, string message)
        { if (!condition) throw new InvalidOperationException(message); }
    }
}
